function pagesFromNode(nodeName) { try { return $(nodeName).all().map(i => i.json).filter(p => p && p.properties); } catch (error) { return []; } }
function prop(page, name) { return page.properties?.[name]; }
function title(page, names) { for (const name of names) { const p = prop(page, name); const value = p?.title?.map(t => t.plain_text || t.text?.content || '').join('').trim(); if (value) return value; } return ''; }
function rich(page, names) { for (const name of names) { const p = prop(page, name); const value = p?.rich_text?.map(t => t.plain_text || t.text?.content || '').join('').trim(); if (value) return value; } return ''; }
function email(page, names) { for (const name of names) { const v = prop(page, name)?.email; if (v) return v; } return ''; }
function url(page, names) { for (const name of names) { const v = prop(page, name)?.url; if (v) return v; } return ''; }
function phone(page, names) { for (const name of names) { const v = prop(page, name)?.phone_number; if (v) return v; } return ''; }
function select(page, names) { for (const name of names) { const v = prop(page, name)?.select?.name || prop(page, name)?.status?.name; if (v) return v; } return ''; }
function number(page, names) { for (const name of names) { const v = prop(page, name)?.number; if (v !== undefined && v !== null) return v; } return null; }
function keyFor(record) { const websiteKey = (record.website || '').replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '').toLowerCase(); if (websiteKey) return 'website:' + websiteKey; if (record.email) return 'email:' + record.email.toLowerCase(); return 'firma:' + [record.companyName, record.city].join('|').toLowerCase().replace(/\s+/g, ' ').trim(); }
function richText(content) { return [{ type: 'text', text: { content: String(content || '').slice(0, 1900) } }]; }
function statusUpdate(pageId, status, reason) { const now = new Date().toISOString(); return { pageId, notionUpdateBody: { properties: { Status: { select: { name: status } }, Fehlergrund: { rich_text: richText(reason) }, 'Workflow Log': { rich_text: richText('OUTREACH INTELLIGENCE SYSTEM V1 | ' + status + ' | ' + reason) }, 'Bearbeitet am': { date: { start: now } } } } }; }
function normalize(page) { return { pageId: page.id, pageUrl: page.url || '', companyName: title(page, ['Firmenname', 'Firma', 'Name']), industry: rich(page, ['Branche']), city: rich(page, ['Ort']), website: url(page, ['Website', 'Quelle / Fundstelle']), contactPerson: rich(page, ['Ansprechpartner']), email: email(page, ['E-Mail', 'Email']), phone: phone(page, ['Telefon']), status: select(page, ['Status']), websiteScore: number(page, ['Website Score', 'Website-Score']), landingpagePotential: select(page, ['Landingpage Potenzial', 'Landingpage-Potenzial']) || rich(page, ['Landingpage Potenzial']), automationPotential: select(page, ['Automations Potenzial', 'Automations-Potenzial']) || rich(page, ['Automations Potenzial']), websiteWeaknesses: rich(page, ['Website Schwächen', 'größte Website-Schwächen', 'Hauptschwachstelle']), offerAngle: rich(page, ['Angebotswinkel', 'empfohlener Angebotswinkel', 'Empfohlene Lösung', 'Was verkaufen']), existingDraft: rich(page, ['E-Mail Entwurf', 'Akquise-Mail']), existingSubject: rich(page, ['Betreff']), notes: rich(page, ['Notizen', 'Audit', 'Verbesserungspotenziale']) }; }
const allPages = pagesFromNode('Fetch All CRM Pages for Duplicate Check');
const allRecords = allPages.map(normalize);
const newPages = allPages.filter(page => normalize(page).status === 'Neu');
const counts = new Map();
for (const record of allRecords) { const key = keyFor(record); counts.set(key, (counts.get(key) || 0) + 1); }
const items = [];
for (const page of newPages) { const record = normalize(page); const reasons = []; if ((record.status || '').trim() !== 'Neu') reasons.push('Status ist nicht Neu'); if (!record.companyName) reasons.push('Firmenname/Firma fehlt'); if (!record.website) reasons.push('Website fehlt'); if (record.existingDraft || record.existingSubject) reasons.push('Entwurf oder Betreff existiert bereits'); const dupCount = counts.get(keyFor(record)) || 0; if (dupCount > 1) reasons.push('Doppelter Betrieb im CRM erkannt (' + dupCount + ' Datensätze)'); const warnings = []; if (!record.email) warnings.push('E-Mail fehlt; Entwurf wird trotzdem erstellt, weil kein automatischer Versand erfolgt'); const base = { ...record, crmDatabaseId: '<REDACTED_ID>', duplicateCount: dupCount, warnings, processedAt: new Date().toISOString() }; if (reasons.length) { const update = statusUpdate(record.pageId, 'Prüfung nötig', reasons.join('; ')); items.push({ json: { ...base, action: 'skip_update', skipReason: reasons.join('; '), ...update } }); } else { items.push({ json: { ...base, action: 'process', skipReason: '', duplicateKey: keyFor(record) } }); } }
return items;

function items(nodeName) { try { return $(nodeName).all().map(i => i.json); } catch (error) { return []; } }
const queue = items('Build Processing Queue and Duplicate Report'); const draftWrites = items('Mark Draft Notion Write'); const aiWrites = items('Mark AI Failure Notion Write'); const skipWrites = items('Mark Skip Notion Write'); const allWrites = [...draftWrites, ...aiWrites, ...skipWrites]; const errors = [];
for (const item of queue) { if (item.skipReason) errors.push({ node: 'Build Processing Queue and Duplicate Report', record: item.companyName || item.pageId, message: item.skipReason, time: new Date().toISOString() }); }
for (const item of allWrites) { if (item.status === 'notion_failed') errors.push({ node: item.resultType === 'draft' ? 'Update Notion with Draft' : item.resultType === 'ai_failure' ? 'Update Notion with AI Failure' : 'Update Notion with Skip Reason', record: item.companyName || item.pageId, message: item.error || 'Notion Schreibfehler', time: new Date().toISOString() }); }
for (const item of aiWrites) { if (item.status === 'ai_failure_logged') errors.push({ node: 'OpenAI Lead Draft Generator', record: item.companyName || item.pageId, message: item.error || 'KI Fehler', time: new Date().toISOString() }); }
return [{ json: { workflow: 'OUTREACH INTELLIGENCE SYSTEM V1', completedAt: new Date().toISOString(), loadedNewLeads: queue.length, processedLeads: queue.filter(i => i.action === 'process').length, skippedLeads: queue.filter(i => i.action !== 'process').length, draftsCreated: draftWrites.filter(i => i.status === 'draft_created').length, aiFailures: aiWrites.filter(i => i.status === 'ai_failure_logged').length, notionWriteFailures: allWrites.filter(i => i.status === 'notion_failed').length, errors } }];

const lead = $('Process One Lead').item.json;
const response = $input.item.json || {};
const rawHtml = String(response.body || response.data || '').slice(0, 60000);
const statusCode = Number(response.statusCode || 0);
function strip(html) { return html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim(); }
function match(re) { const m = rawHtml.match(re); return m ? m[1].replace(/\s+/g, ' ').trim() : ''; }
const text = strip(rawHtml).slice(0, 9000);
const lower = rawHtml.toLowerCase();
const signals = { hasViewport: lower.includes('name="viewport') || lower.includes("name='viewport"), hasForm: lower.includes('<form') || lower.includes('kontaktformular'), hasCta: /angebot|anfrage|kontakt|termin|beratung|rückruf/i.test(text), hasTrust: /bewertung|referenz|zertifikat|meister|innung|kunden|partner|google/i.test(text), hasLocalSeo: Boolean(lead.city && text.toLowerCase().includes(String(lead.city).toLowerCase().split(/[\/,-]/)[0].trim())), looksModern: /lazy|schema.org|json-ld|webp|srcset|font-display|module/i.test(rawHtml) };
const missing = Object.entries(signals).filter(([, value]) => !value).map(([key]) => key);
const aiInput = { lead: { companyName: lead.companyName, industry: lead.industry, city: lead.city, website: lead.website, contactPerson: lead.contactPerson, email: lead.email, phone: lead.phone, websiteScore: lead.websiteScore, existingLandingpagePotential: lead.landingpagePotential, existingAutomationPotential: lead.automationPotential, existingWebsiteWeaknesses: lead.websiteWeaknesses, existingOfferAngle: lead.offerAngle, notes: lead.notes, warnings: lead.warnings }, websiteEvidence: { statusCode, title: match(/<title[^>]*>([\s\S]*?)<\/title>/i), description: match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i), textSample: text, signals, missingSignals: missing }, rules: { language: 'Deutsch', tone: 'professionell, seriös, ruhig', maxEmailWords: 150, noInventedFacts: true, noAutomaticSending: true } };
return { json: { ...lead, websiteFetchStatusCode: statusCode, websiteSignals: signals, websiteMissingSignals: missing, websiteTextSample: text.slice(0, 2000), aiInput } };

const lead = $('Analyze Website Evidence').item.json;
const item = $input.item.json || {};
function text(v) { return String(v || '').trim(); }
function limitWords(value, maxWords) { const words = text(value).split(/\s+/).filter(Boolean); return words.length > maxWords ? words.slice(0, maxWords).join(' ') : words.join(' '); }
function parseOutput(raw) { if (!raw) return null; if (typeof raw === 'object') return raw; let cleaned = String(raw).trim(); const fence = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96); if (cleaned.startsWith(fence)) cleaned = cleaned.replace(fence + 'json', '').replace(fence, '').replace(fence, '').trim(); return JSON.parse(cleaned); }
try { if (lead.simulateOpenAiFailure || item.error || item.message?.includes?.('error')) throw new Error(item.error?.message || item.message || 'OpenAI Fehler'); const parsed = parseOutput(item.output || item.text || item.response || item); if (!parsed || !parsed.emailDraft || !parsed.subject) throw new Error('OpenAI Antwort enthaelt keinen Betreff oder Entwurf'); return { json: { ...lead, aiStatus: 'success', subject: text(parsed.subject).slice(0, 180), emailDraft: limitWords(parsed.emailDraft, 150), shortSummary: text(parsed.shortSummary).slice(0, 1000), mainArgument: text(parsed.mainArgument).slice(0, 1000), callToAction: text(parsed.callToAction).slice(0, 500), offerAngle: text(parsed.offerAngle || lead.offerAngle).slice(0, 1000), landingpagePotentialFinal: text(parsed.landingpagePotential).slice(0, 1000), automationPotentialFinal: text(parsed.automationPotential).slice(0, 1000), websiteWeaknessesFinal: text(parsed.websiteWeaknesses || lead.websiteWeaknesses).slice(0, 1500), websiteScoreFinal: Number(parsed.websiteScore ?? lead.websiteScore ?? 0) } }; } catch (error) { return { json: { ...lead, aiStatus: 'failed', aiError: error.message || String(error) } }; }

const lead = $input.item.json;
function rich(content) { return [{ type: 'text', text: { content: String(content || '').slice(0, 1900) } }]; }
const now = new Date().toISOString();
const log = ['Entwurf erstellt', lead.warnings?.join('; ') || '', 'Website HTTP: ' + (lead.websiteFetchStatusCode || 'unbekannt')].filter(Boolean).join(' | ');
return { json: { ...lead, notionWriteType: 'draft', notionUpdateBody: { properties: { Status: { select: { name: 'Entwurf erstellt' } }, Betreff: { rich_text: rich(lead.subject) }, 'E-Mail Entwurf': { rich_text: rich(lead.emailDraft) }, 'Akquise-Mail': { rich_text: rich(lead.emailDraft) }, Kurzfassung: { rich_text: rich(lead.shortSummary) }, Hauptargument: { rich_text: rich(lead.mainArgument) }, CTA: { rich_text: rich(lead.callToAction) }, Angebotswinkel: { rich_text: rich(lead.offerAngle) }, 'empfohlener Angebotswinkel': { rich_text: rich(lead.offerAngle) }, Erstellungsdatum: { date: { start: now.slice(0, 10) } }, 'Bearbeitet am': { date: { start: now } }, 'Website Schwächen': { rich_text: rich(lead.websiteWeaknessesFinal) }, 'Landingpage Potenzial': { rich_text: rich(lead.landingpagePotentialFinal) }, 'Automations Potenzial': { rich_text: rich(lead.automationPotentialFinal) }, Fehlergrund: { rich_text: [] }, 'Workflow Log': { rich_text: rich(log) } } } } };
